class _StatusBadge extends StatelessWidget {
  const _StatusBadge({required this.status, this.label});

  final String status;
  final String? label;

  @override
  Widget build(BuildContext context) {
    final normalized = status.trim().toLowerCase();
    final scheme = Theme.of(context).colorScheme;
    final color = switch (normalized) {
      'available' || 'received' => scheme.primaryContainer,
      'rejected' || 'cancelled' => scheme.errorContainer,
      _ => scheme.tertiaryContainer,
    };
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
      decoration: BoxDecoration(
        color: color,
        borderRadius: BorderRadius.circular(999),
      ),
      child: Text(
        label == null ? _statusLabel(normalized) : localizeUrduUiText(label!),
        style: Theme.of(context).textTheme.labelSmall,
      ),
    );
  }
}
